	const fileCount = 10
	for i := 0; i < fileCount; i++ {
		if err := os.WriteFile(filepath.Join(dir, fmt.Sprintf("file%d.go", i)), []byte(fmt.Sprintf("content %d", i)), 0o644); err != nil {
